                                                                                                                                                                                                                      
  CREATE TABLE "TENANT_DISPATCH_CONFIG"                                                                                                                                                                    
   (	"DISPATCH_CONFIG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                           
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                           
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                  
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                             
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                  
	"IS_GLOBAL" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                        
	"EXT_ORG_ID" NUMBER(32,0),                                                                                                                                                                                           
	"NAME" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                                                
	"IS_ENABLE" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                        
	"BEGIN_TIME" NVARCHAR2(10) DEFAULT '00:00' NOT NULL ENABLE,                                                                                                                                                          
	"END_TIME" NVARCHAR2(10) DEFAULT '00:00' NOT NULL ENABLE,                                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                        
	 PRIMARY KEY ("DISPATCH_CONFIG_ID")                                                                                                                                                                                  
